import{b as a,O as s,g as i,j as n}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"白盒与黑盒","description":"","frontmatter":{},"headers":[],"relativePath":"testing/methodology/white-black-box/index.md","filePath":"测试理论与实践/3.测试方法体系/07.白盒与黑盒.md","lastUpdated":1781688244000}'),e={name:"testing/methodology/white-black-box/index.md"};function l(h,t,d,p,o,r){return s(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="白盒与黑盒" tabindex="-1">白盒与黑盒 <a class="header-anchor" href="#白盒与黑盒" aria-label="Permalink to &quot;白盒与黑盒&quot;">​</a></h1><blockquote><p>黑盒测试像&quot;用户&quot;，只关心输入和输出，不管里面怎么实现的。白盒测试像&quot;修理工&quot;，打开盖子看代码逻辑，确保每一条路都没走岔。</p></blockquote><h2 id="两大视角-黑盒与白盒" tabindex="-1">两大视角：黑盒与白盒 <a class="header-anchor" href="#两大视角-黑盒与白盒" aria-label="Permalink to &quot;两大视角：黑盒与白盒&quot;">​</a></h2><p>测试设计有两种截然不同的出发点：</p><table tabindex="0"><thead><tr><th>视角</th><th>核心问题</th><th>需要看源码吗</th><th>打个比方</th></tr></thead><tbody><tr><td><strong>黑盒测试</strong></td><td>&quot;这个功能做对了吗？&quot;</td><td>不需要</td><td>不拆手机壳，只按屏幕，看功能是否正常</td></tr><tr><td><strong>白盒测试</strong></td><td>&quot;这段代码每条路径都走通了吗？&quot;</td><td>需要</td><td>打开手机，用万用表测每一根线路</td></tr></tbody></table><p>两者不是对立关系，而是<strong>覆盖不同维度的风险</strong>。黑盒发现需求理解和功能层面的问题，白盒发现代码逻辑和实现层面的问题。只做黑盒，代码里的 dead code 和逻辑死角永远发现不了；只做白盒，你可能覆盖了所有代码路径但做出来的根本不是用户要的功能。</p><h2 id="黑盒测试-从用户视角出发" tabindex="-1">黑盒测试：从用户视角出发 <a class="header-anchor" href="#黑盒测试-从用户视角出发" aria-label="Permalink to &quot;黑盒测试：从用户视角出发&quot;">​</a></h2><p>黑盒测试的核心假设是：<strong>我不知道里面怎么实现的，我只知道输入什么、应该输出什么。</strong> 这个假设恰好符合用户的真实使用场景——用户也不知道你的代码长什么样。</p><p><a href="/testing/basics/test-case-design.html">测试用例设计方法论</a>讲的等价类划分、边界值分析、因果图、决策表、错误猜测——这些本质上都是黑盒方法。它们不依赖源码，从需求规格说明书出发设计用例。</p><p>黑盒测试能发现的问题：</p><ul><li>功能实现不正确或不完整</li><li>接口之间的数据传递错误</li><li>用户操作路径不合理（比如要先点 A 才能点 B，但用户习惯先点 B）</li><li>需求理解偏差（开发实现的和产品想要的不是一回事）</li></ul><p>黑盒测试的盲区：</p><ul><li>代码里有一段&quot;理论上永远不会执行&quot;的逻辑——但你不知道它的存在</li><li>某个 if-else 分支写反了，但恰好测试数据没覆盖到这个边界</li><li>代码逻辑实现了但效率极低——循环嵌套了三层实际两层就够</li></ul><blockquote><p>这也是为什么黑盒不够，还需要白盒。</p></blockquote><h2 id="白盒测试-打开盖子看代码" tabindex="-1">白盒测试：打开盖子看代码 <a class="header-anchor" href="#白盒测试-打开盖子看代码" aria-label="Permalink to &quot;白盒测试：打开盖子看代码&quot;">​</a></h2><p>白盒测试的核心是<strong>逻辑覆盖</strong>——你看着代码，确保每一行、每一个分支、每一个条件都被测试执行过。</p><p>白盒测试有五层递增的覆盖标准，从低到高逐步逼近&quot;充分测试&quot;：</p><h3 id="_1-语句覆盖" tabindex="-1">1. 语句覆盖 <a class="header-anchor" href="#_1-语句覆盖" aria-label="Permalink to &quot;1. 语句覆盖&quot;">​</a></h3><p><strong>每条语句至少执行一次。</strong></p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> score </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;及格&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 语句 A</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;不及格&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 语句 B</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;成绩已录入&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 语句 C</span></span></code></pre></div><p>语句覆盖只需要一个用例：<code>score = 70</code>，执行 A 和 C，B 没有执行。语句覆盖覆盖率最低——连 else 都没走，你就敢说测完了？</p><h3 id="_2-分支覆盖-判定覆盖" tabindex="-1">2. 分支覆盖（判定覆盖） <a class="header-anchor" href="#_2-分支覆盖-判定覆盖" aria-label="Permalink to &quot;2. 分支覆盖（判定覆盖）&quot;">​</a></h3><p><strong>每个判断的真假分支至少走一次。</strong></p><p>同一个例子，需要两个用例：</p><ul><li><code>score = 70</code> → 走&quot;真&quot;分支（及格）</li><li><code>score = 50</code> → 走&quot;假&quot;分支（不及格）</li></ul><blockquote><p>分支覆盖比语句覆盖强，但还不够——如果 <code>score &gt;= 60</code> 被开发误写成了 <code>score &gt; 60</code>，两个用例分别是 70 和 50，结果分别是&quot;及格&quot;和&quot;不及格&quot;，都符合预期，但 60 分那个边界会被漏掉。</p></blockquote><h3 id="_3-条件覆盖" tabindex="-1">3. 条件覆盖 <a class="header-anchor" href="#_3-条件覆盖" aria-label="Permalink to &quot;3. 条件覆盖&quot;">​</a></h3><p><strong>每个条件中的每个子条件，真假都至少取一次。</strong></p><p>当 <code>if</code> 里有多个条件组合时有用：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 18</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> and</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    allow_purchase()</span></span></code></pre></div><p>语句覆盖和分支覆盖可能只用了 <code>age=20, balance=200</code>（全真）和 <code>age=15, balance=50</code>（全假）。但如果 <code>and</code> 被写成了 <code>or</code>，这两个用例测不出来。</p><p>条件覆盖需要每个子条件独立真和假：</p><table tabindex="0"><thead><tr><th>用例</th><th>age &gt;= 18</th><th>balance &gt;= 100</th></tr></thead><tbody><tr><td>age=20, balance=50</td><td>True</td><td>False</td></tr><tr><td>age=15, balance=200</td><td>False</td><td>True</td></tr></tbody></table><p>这样组合覆盖到了，但注意——条件覆盖不要求走遍所有分支组合。如果 <code>and</code> 写成了 <code>or</code>，<code>age=20, balance=50</code> 这条预期不该购买却购买了，bug 就被逮到了。</p><h3 id="_4-条件组合覆盖" tabindex="-1">4. 条件组合覆盖 <a class="header-anchor" href="#_4-条件组合覆盖" aria-label="Permalink to &quot;4. 条件组合覆盖&quot;">​</a></h3><p><strong>所有子条件的所有真/假组合都至少测试一次。</strong></p><p>上面两个条件的全部组合：</p><table tabindex="0"><thead><tr><th>age &gt;= 18</th><th>balance &gt;= 100</th><th>用例</th></tr></thead><tbody><tr><td>True</td><td>True</td><td>age=20, balance=200</td></tr><tr><td>True</td><td>False</td><td>age=20, balance=50</td></tr><tr><td>False</td><td>True</td><td>age=15, balance=200</td></tr><tr><td>False</td><td>False</td><td>age=15, balance=50</td></tr></tbody></table><p>n 个子条件就有 2^n 种组合。这是条件层面的穷举。实际项目中条件多了组合爆炸，优先覆盖&quot;每个条件独立影响结果&quot;的用例更实际。</p><h3 id="_5-路径覆盖" tabindex="-1">5. 路径覆盖 <a class="header-anchor" href="#_5-路径覆盖" aria-label="Permalink to &quot;5. 路径覆盖&quot;">​</a></h3><p><strong>程序的每一种可能的执行路径至少走一次。</strong></p><p>这是最强的覆盖标准——不只看条件，还看循环次数和函数调用链。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> process</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 路径分叉 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        a()           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 路径 A</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        b()           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 路径 B</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 路径分叉 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        c()           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 路径 X</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        d()           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 路径 Y</span></span></code></pre></div><p>可能的完整路径：A→X, A→Y, B→X, B→Y —— 四条。如果有循环，循环不同次数也是不同的路径，路径数爆炸。</p><p>这里的结论很务实：<strong>路径覆盖在理论上完美，在实践中不可行。</strong> 你不可能覆盖所有路径，但可以通过这五种覆盖标准，从低到高逐步逼近&quot;充分测试&quot;。</p><h3 id="五种覆盖标准的关系" tabindex="-1">五种覆盖标准的关系 <a class="header-anchor" href="#五种覆盖标准的关系" aria-label="Permalink to &quot;五种覆盖标准的关系&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语句覆盖 ⊂ 分支覆盖 ⊂ 条件覆盖 ⊂ 条件组合覆盖 ⊂ 路径覆盖</span></span>
<span class="line"><span>(最弱)                                 (最强/不现实)</span></span></code></pre></div><ul><li>语句覆盖是底线——你至少每行代码都跑过</li><li>分支覆盖是基本要求——每个 if-else 两个方向都走过</li><li>条件覆盖是进阶——确保每个子条件独立地&quot;真&quot;和&quot;假&quot;都发生过</li><li>条件组合覆盖和路径覆盖是理想——追求它，但别苛求所有场景都达到</li></ul><h3 id="实践中做到哪一步就够了" tabindex="-1">实践中做到哪一步就够了 <a class="header-anchor" href="#实践中做到哪一步就够了" aria-label="Permalink to &quot;实践中做到哪一步就够了&quot;">​</a></h3><p>下面是一个务实的坐标尺，帮你判断&quot;够不够&quot;：</p><table tabindex="0"><thead><tr><th>级别</th><th>目标</th><th>什么时候达标</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>底线</strong></td><td>语句覆盖</td><td>每行代码都至少执行过一次</td><td>所有代码，不可商量</td></tr><tr><td><strong>基本要求</strong></td><td>分支覆盖</td><td>每个 if-else 真/假都走过</td><td>所有业务逻辑代码</td></tr><tr><td><strong>进阶</strong></td><td>条件覆盖</td><td>每个子条件的真/假独立验证过</td><td>复杂判断逻辑、计算规则</td></tr><tr><td><strong>理想</strong></td><td>条件组合 + 路径覆盖</td><td>追求但别苛求</td><td>关键模块（支付、安全、核心算法）</td></tr></tbody></table><p><strong>核心原则</strong>：不是在所有代码上追求最高覆盖标准，而是<strong>按风险分级</strong>——支付逻辑的条件覆盖做到 100%，日志打印的语句覆盖够了就行。如果团队资源有限，优先把所有代码拉到&quot;分支覆盖&quot;，再对高风险模块加码到&quot;条件覆盖&quot;。</p><h2 id="测试金字塔-按层次组织测试" tabindex="-1">测试金字塔：按层次组织测试 <a class="header-anchor" href="#测试金字塔-按层次组织测试" aria-label="Permalink to &quot;测试金字塔：按层次组织测试&quot;">​</a></h2><p>白盒和黑盒讲的是&quot;怎么看&quot;，测试金字塔讲的是&quot;在哪里测&quot;。</p><p>业界有两个相似的分层模型：</p><table tabindex="0"><thead><tr><th>传统分层</th><th>另一种常见分法</th><th>范围</th><th>速度</th><th>数量占比</th></tr></thead><tbody><tr><td>单元测试</td><td>小型测试</td><td>单个函数/类，无外部依赖</td><td>毫秒级</td><td>~70%</td></tr><tr><td>集成测试</td><td>中型测试</td><td>模块间交互，可有文件/DB</td><td>秒级</td><td>~20%</td></tr><tr><td>系统/验收测试</td><td>大型测试</td><td>端到端全链路</td><td>分钟级</td><td>~10%</td></tr></tbody></table><p>金字塔的核心逻辑是：<strong>越底层的测试越快、越稳定、成本越低，所以应该写得最多。越上层的测试越慢、越容易因环境波动而失败，所以应该写得少而精。</strong></p><p>反模式是&quot;冰淇淋筒&quot;——单元测试几乎没有，大量依赖手工端到端测试。这种模式下，问题发现得太晚，反馈太慢。</p><h2 id="模块测试的集成策略" tabindex="-1">模块测试的集成策略 <a class="header-anchor" href="#模块测试的集成策略" aria-label="Permalink to &quot;模块测试的集成策略&quot;">​</a></h2><p>写完单元测试、测完单个模块，接下来要把模块拼起来测。集成策略的选择是绕不开的决策。</p><h3 id="非增量式-vs-增量式" tabindex="-1">非增量式 vs 增量式 <a class="header-anchor" href="#非增量式-vs-增量式" aria-label="Permalink to &quot;非增量式 vs 增量式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>做法</th><th>优缺点</th></tr></thead><tbody><tr><td><strong>非增量式（大爆炸）</strong></td><td>所有模块独立测完，一次性拼起来再测</td><td>简单粗暴，但出了问题很难定位是哪个模块的锅</td></tr><tr><td><strong>增量式</strong></td><td>一个一个模块加进去，每加一个就测一轮</td><td>问题一出现就知道是新加模块导致的，但过程较慢</td></tr></tbody></table><blockquote><p>除非项目极小，永远选增量式。大爆炸集成一出问题，排查时间远大于增量测试多花的功夫。</p></blockquote><h3 id="增量式的两种方向" tabindex="-1">增量式的两种方向 <a class="header-anchor" href="#增量式的两种方向" aria-label="Permalink to &quot;增量式的两种方向&quot;">​</a></h3><p>选择了增量式之后，还要决定&quot;从哪开始加&quot;：</p><h4 id="自顶向下-top-down" tabindex="-1">自顶向下（Top-Down） <a class="header-anchor" href="#自顶向下-top-down" aria-label="Permalink to &quot;自顶向下（Top-Down）&quot;">​</a></h4><p>从最上层的控制模块开始，逐层往下加。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    [主控模块]  ← 先测这个（桩程序替代下层）</span></span>
<span class="line"><span>     /    \\</span></span>
<span class="line"><span> [下单]   [支付]  ← 再加这些</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span> [库存]  ← 最后这个</span></span></code></pre></div><ul><li><strong>优点</strong>：早期就能看到系统主流程跑通</li><li><strong>缺点</strong>：底层模块要到最后才能验证，需要写很多&quot;桩程序&quot;（stub）模拟下层行为</li></ul><h4 id="自底向上-bottom-up" tabindex="-1">自底向上（Bottom-Up） <a class="header-anchor" href="#自底向上-bottom-up" aria-label="Permalink to &quot;自底向上（Bottom-Up）&quot;">​</a></h4><p>从最底层的功能模块开始，逐层往上拼。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  [库存] [支付]  ← 先测这些（驱动模块调用）</span></span>
<span class="line"><span>      \\   /</span></span>
<span class="line"><span>      [下单]  ← 再拼这一层</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>      [主控]  ← 最后到顶部</span></span></code></pre></div><ul><li><strong>优点</strong>：底层模块测得最充分，不需要写桩程序</li><li><strong>缺点</strong>：主流程到最后才能看到，早期看不出产品长什么样</li></ul><h4 id="怎么选" tabindex="-1">怎么选？ <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选？&quot;">​</a></h4><p>实际经验是：<strong>大多数项目应该结合使用。</strong></p><p>可以在项目前期用自顶向下验证主流程和架构，同时用自底向上充分测试底层关键模块（比如数据库访问层），最后在中间层汇合。这种叫<strong>三明治集成</strong>。</p><blockquote><p>选集成策略的核心依据不是技术偏好，是风险。如果最怕主流程出问题，优先自顶向下；如果最怕底层数据处理出错（比如金融系统），优先自底向上。</p></blockquote><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>黑盒不看源码，从用户视角验证功能是否正确；白盒看源码，确保代码逻辑每一条路都走到</li><li>白盒五种覆盖标准递进：语句覆盖（底线）→ 分支覆盖（基本）→ 条件覆盖（进阶）→ 条件组合覆盖 → 路径覆盖</li><li>实践中<strong>按风险分级定标准</strong>——所有代码至少做到分支覆盖，高风险模块（支付、安全、核心算法）追条件覆盖，别一刀切追求最高标准</li><li>测试金字塔：70% 单元测试（快且稳）+ 20% 集成测试 + 10% 端到端测试，越底层越要多</li><li>集成测试选增量式不选大爆炸——出了问题秒定位。增量式的方向（自顶向下/自底向上）按风险选</li></ol>`,79)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
